import fs from "node:fs"
import path from "node:path"

import { PACKAGE_ROOT } from "./paths"
import type { IconElement } from "./types"

const GENERATED_HEADER =
  "// Generated by @fabricator-ui/icons-core. Do not edit.\n"

/**
 * Makes `directory` hold exactly `files` (relative path → content): writes
 * what changed and deletes what is no longer generated. Unchanged files keep
 * their mtime, so watchers don't rebuild for nothing.
 */
export function writeGeneratedDirectory(
  directory: string,
  files: Map<string, string>
) {
  fs.mkdirSync(directory, { recursive: true })
  const existing = new Set(
    (fs.readdirSync(directory, { recursive: true }) as string[])
      .filter((file) => fs.statSync(path.join(directory, file)).isFile())
      .map((file) => file.split(path.sep).join("/"))
  )
  let written = 0
  for (const [relative, content] of files) {
    existing.delete(relative)
    const file = path.join(directory, relative)
    if (fs.existsSync(file) && fs.readFileSync(file, "utf8") === content)
      continue
    fs.mkdirSync(path.dirname(file), { recursive: true })
    fs.writeFileSync(file, content)
    written += 1
  }
  for (const stale of existing) fs.rmSync(path.join(directory, stale))
  return { written, removed: existing.size }
}

/** Writes one file when its content changed. */
export function writeGeneratedFile(file: string, content: string) {
  if (fs.existsSync(file) && fs.readFileSync(file, "utf8") === content)
    return false
  fs.mkdirSync(path.dirname(file), { recursive: true })
  fs.writeFileSync(file, content)
  return true
}

/** The runtime helpers every package bundles, keyed by file name. */
export function readRuntimeFiles() {
  const directory = path.join(PACKAGE_ROOT, "src", "runtime")
  const files = new Map<string, string>()
  for (const file of fs.readdirSync(directory).sort()) {
    if (!file.endsWith(".ts") || file.endsWith(".test.ts")) continue
    files.set(
      file,
      GENERATED_HEADER + fs.readFileSync(path.join(directory, file), "utf8")
    )
  }
  return files
}

export function withGeneratedHeader(content: string) {
  return GENERATED_HEADER + content
}

/** `stroke-width` → `strokeWidth`, for React and react-native-svg. */
export function toCamelCaseAttributes(node: IconElement[]): IconElement[] {
  return node.map(([tag, attributes]) => [
    tag,
    Object.fromEntries(
      Object.entries(attributes).map(([name, value]) => [
        name.replace(/-([a-z])/g, (_, letter: string) => letter.toUpperCase()),
        value,
      ])
    ),
  ])
}
